    area = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)
    if area == 0: return
    if area < 0:
        tx, ty, tz = x1, y1, z1
        x1, y1, z1 = x2, y2, z2
        x2, y2, z2 = tx, ty, tz
        area = -area
