    miny0 = min(y0, y1, y2); maxy0 = max(y0, y1, y2)
    minx = max(0, math.ceil(minx0 - 0.5)); maxx = min(__FB_W - 1, math.floor(maxx0 - 0.5))
    miny = max(0, math.ceil(miny0 - 0.5)); maxy = min(__FB_H - 1, math.floor(maxy0 - 0.5))
