            e0 = (x2 - x1) * (cy - y1) - (y2 - y1) * (cx - x1)
            e1 = (x0 - x2) * (cy - y2) - (y0 - y2) * (cx - x2)
            e2 = (x1 - x0) * (cy - y0) - (y1 - y0) * (cx - x0)
