class StrBuf:
    def __init__(self, parts=None):
        self.parts = parts

    def push(self, s):
        self.parts.append(s)

    def push_num(self, n):
        self.parts.append(str(n))

    def push_float(self, n):
        self.parts.append(str(n))

    def part_count(self):
        return _len(self.parts)

    def build(self):
        return "".join(self.parts)

    def build_sep(self, sep):
        return sep.join(self.parts)

    def clear(self):
        while (_len(self.parts) > 0):
            self.parts.pop()

def strbuf_new():
    v1_parts = []
    return StrBuf(parts=v1_parts)

